386	+import { HttpErrorResponse } from '@angular/common/http';
387	+import { Component, inject, signal } from '@angular/core';
388	+import { Router } from '@angular/router';
389	+
390	+import { BookingService } from '../../../core/services/booking.service';
391	+
392	+@Component({
393	+  selector: 'app-buchung-abrufen-page',
394	+  imports: [],
395	+  templateUrl: './buchung-abrufen-page.html',
396	+  styleUrl: './buchung-abrufen-page.scss'
397	+})
398	+export class BuchungAbrufenPage {
399	+  private readonly router = inject(Router);
400	+  private readonly bookingService = inject(BookingService);
401	+
402	+  protected readonly reference = signal('');
403	+  protected readonly submitting = signal(false);
404	+  protected readonly errorMessage = signal<string | null>(null);
405	+
406	+  protected onReferenceInput(value: string): void {
407	+    this.reference.set(value);
408	+  }
409	+
410	+  protected onSubmit(event: Event): void {
411	+    event.preventDefault();
412	+    const reference = this.reference().trim();
413	+    if (!reference) {
414	+      this.errorMessage.set('Bitte geben Sie eine Buchungsreferenz ein.');
415	+      return;
416	+    }
417	+
418	+    this.errorMessage.set(null);
419	+    this.submitting.set(true);
420	+
421	+    this.bookingService.getBooking(reference).subscribe({
422	+      next: (booking) => {
423	+        this.submitting.set(false);
424	+        this.router.navigate(['/buchungen', reference], { state: { booking } });
425	+      },
426	+      error: (err: HttpErrorResponse) => {
427	+        this.submitting.set(false);
428	+        this.errorMessage.set(
429	+          err.status === 404
430	+            ? 'Keine Buchung mit dieser Referenz gefunden.'
431	+            : 'Buchung konnte nicht abgerufen werden. Bitte versuchen Sie es erneut.'
432	+        );
433	+      }
434	+    });
435	+  }
436	+}
