23	public class BookingService(AppDbContext dbContext)
24	{
25	    public async Task<CreateBookingResult> CreateBookingAsync(CreateBookingRequestDto request)
26	    {
27	        var invalidFields = new List<string>();
28	        if (string.IsNullOrWhiteSpace(request.Name)) invalidFields.Add("name");
29	        if (string.IsNullOrWhiteSpace(request.Email)) invalidFields.Add("email");
30	        if (request.Seats is null || request.Seats.Count == 0) invalidFields.Add("seats");
31	        if (invalidFields.Count > 0)
32	        {
33	            return CreateBookingResult.Invalid(invalidFields, "Pflichtangaben fehlen.");
34	        }
35	
36	        var seatIds = request.Seats!.Select(s => s.SeatId).ToList();
37	        if (seatIds.Distinct().Count() != seatIds.Count)
38	        {
39	            return CreateBookingResult.Invalid(["seats"], "Ein Sitzplatz wurde mehrfach angefragt.");
40	        }
41	
42	        var room = await dbContext.Events
43	            .Where(e => e.Id == request.EventId)
44	            .Select(e => (Guid?)e.RoomId)
45	            .FirstOrDefaultAsync();
46	        if (room is null)
47	        {
48	            return CreateBookingResult.Invalid(["seats"], "Unbekannte Veranstaltung.");
49	        }
50	
51	        var validSeatIds = await dbContext.Seats
52	            .Where(s => s.RoomId == room.Value && seatIds.Contains(s.Id))
53	            .Select(s => s.Id)
54	            .ToListAsync();
55	        var validCategoryIds = await dbContext.PriceCategories
56	            .Where(pc => pc.EventId == request.EventId)
57	            .Select(pc => pc.Id)
58	            .ToListAsync();
59	        var hasInvalidSeatOrCategory = request.Seats!.Any(s =>
60	            !validSeatIds.Contains(s.SeatId) || !validCategoryIds.Contains(s.PriceCategoryId));
61	        if (hasInvalidSeatOrCategory)
62	        {
63	            return CreateBookingResult.Invalid(["seats"], "Ein Sitzplatz oder eine Preiskategorie ist ungültig.");
64	        }
65	
66	        // EF Core InMemory (Unit-Tests, AC7) unterstützt keine echten Transaktionen — nur bei
67	        // relationalen Providern (SQL Server) wird eine echte Transaktion gestartet.
68	        await using IDbContextTransaction? transaction = dbContext.Database.IsRelational()
69	            ? await dbContext.Database.BeginTransactionAsync(System.Data.IsolationLevel.ReadCommitted)
70	            : null;
71	
72	        // Schritt 1 (AD-1): aktive Konflikte lesen, BEVOR irgendetwas eingefügt wird.
73	        var conflictingSeatIds = await dbContext.BookingSeats
74	            .Where(bs => bs.EventId == request.EventId && bs.IsActive && seatIds.Contains(bs.SeatId))
75	            .Select(bs => bs.SeatId)
76	            .ToListAsync();
77	
78	        if (conflictingSeatIds.Count > 0)
79	        {
80	            if (transaction is not null) await transaction.RollbackAsync();
81	            return CreateBookingResult.Conflict(await SeatLabelsAsync(conflictingSeatIds));
82	        }
83	
84	        var reference = await GenerateUniqueReferenceAsync();
85	        var booking = new Booking
86	        {
87	            Id = Guid.NewGuid(),
88	            Reference = reference,
89	            EventId = request.EventId,
90	            Name = request.Name!.Trim(),
91	            Email = request.Email!.Trim(),
92	            Status = BookingStatus.Active
93	        };
94	        dbContext.Bookings.Add(booking);
95	
96	        foreach (var seat in request.Seats!)
97	        {
98	            dbContext.BookingSeats.Add(new BookingSeat
99	            {
100	                Id = Guid.NewGuid(),
101	                BookingId = booking.Id,
102	                EventId = request.EventId,
103	                SeatId = seat.SeatId,
104	                PriceCategoryId = seat.PriceCategoryId,
105	                IsActive = true
106	            });
107	        }
108	
109	        try
110	        {
111	            // Schritt 2 (AD-1): Insert — der filtered unique index fängt eine echte Race
112	            // zwischen Schritt 1 und 2 zweier gleichzeitiger Transaktionen ab.
113	            await dbContext.SaveChangesAsync();
114	            if (transaction is not null) await transaction.CommitAsync();
115	        }
116	        catch (DbUpdateException)
117	        {
118	            if (transaction is not null) await transaction.RollbackAsync();
119	            dbContext.ChangeTracker.Clear();
120	            var stillConflicting = await dbContext.BookingSeats
121	                .Where(bs => bs.EventId == request.EventId && bs.IsActive && seatIds.Contains(bs.SeatId))
122	                .Select(bs => bs.SeatId)
123	                .ToListAsync();
124	            if (stillConflicting.Count == 0)
125	            {
126	                // Der SaveChanges-Fehlschlag kam nicht vom Sitzplatz-Unique-Index (AD-1) —
127	                // z. B. eine Referenz-Kollision (AD-3) oder ein transienter DB-Fehler. Als
128	                // Sitzplatzkonflikt zu melden wäre irreführend (leere conflictingSeats-Liste).
129	                throw;
130	            }
131	            return CreateBookingResult.Conflict(await SeatLabelsAsync(stillConflicting));
132	        }
133	
134	        return CreateBookingResult.Success(await BuildBookingDtoAsync(booking.Id));
135	    }
136	
137	    private async Task<List<string>> SeatLabelsAsync(List<Guid> seatIds) =>
138	        await dbContext.Seats
139	            .Where(s => seatIds.Contains(s.Id))
140	            .Select(s => s.Row + s.Column.ToString())
141	            .ToListAsync();
142	
143	    private async Task<string> GenerateUniqueReferenceAsync()
144	    {
145	        for (var attempt = 0; attempt < 5; attempt++)
146	        {
147	            var candidate = BookingReferenceGenerator.Generate();
148	            if (!await dbContext.Bookings.AnyAsync(b => b.Reference == candidate))
149	            {
150	                return candidate;
151	            }
152	        }
153	        throw new InvalidOperationException("Konnte keine eindeutige Buchungsreferenz erzeugen.");
154	    }
155	
156	    public async Task<BookingDto?> GetBookingByReferenceAsync(string reference)
157	    {
158	        var bookingId = await dbContext.Bookings
159	            .Where(b => b.Reference == reference)
160	            .Select(b => (Guid?)b.Id)
161	            .FirstOrDefaultAsync();
162	
163	        return bookingId is null ? null : await BuildBookingDtoAsync(bookingId.Value);
164	    }
165	
166	    private async Task<BookingDto> BuildBookingDtoAsync(Guid bookingId)
167	    {
168	        var booking = await dbContext.Bookings
169	            .Where(b => b.Id == bookingId)
170	            .Select(b => new
171	            {
172	                b.Reference,
173	                b.EventId,
174	                b.Status,
175	                EventTitle = b.Event!.Titel,
176	                VenueName = b.Event!.Venue!.Name,
177	                StartsAt = b.Event!.Zeitpunkt
178	            })
179	            .SingleAsync();
180	
181	        var seats = await dbContext.BookingSeats
182	            .Where(bs => bs.BookingId == bookingId)
183	            .Join(dbContext.Seats, bs => bs.SeatId, s => s.Id, (bs, s) => new { bs, s })
184	            .Join(dbContext.PriceCategories, x => x.bs.PriceCategoryId, pc => pc.Id, (x, pc) =>
185	                new BookingSeatDto(x.s.Id, x.s.Row, x.s.Column, pc.Id, pc.Name, pc.Preis))
186	            .ToListAsync();
187	
188	        var totalCents = seats.Sum(s => (long)Math.Round(s.Price * 100));
189	        return new BookingDto(booking.Reference, booking.EventId, booking.EventTitle, booking.VenueName, booking.StartsAt, booking.Status.ToString(), seats, totalCents / 100m);
190	    }
191	}
