19	            return ValidationProblem(new ValidationProblemDetails(errors) { Status = StatusCodes.Status400BadRequest });
20	        }
21	
22	        if (result.ConflictingSeats is not null)
23	        {
24	            return Problem(
25	                title: "Sitzplatzkonflikt",
26	                detail: "Mindestens ein ausgewählter Sitzplatz ist inzwischen vergeben.",
27	                statusCode: StatusCodes.Status409Conflict,
28	                extensions: new Dictionary<string, object?> { ["conflictingSeats"] = result.ConflictingSeats });
29	        }
30	
31	        return StatusCode(StatusCodes.Status201Created, result.Booking);
32	    }
